+
+  it("keeps the menu open on clicks and Escape while the dialog is open", () => {
+    vi.useFakeTimers();
+    const onDismiss = vi.fn();
+    openDialog(vi.fn<SaveRelationType>(), onDismiss);
+    act(() => {
