import { refreshCanvasRelations } from "~/components/canvas/refreshCanvasRelations";
import { discourseContext } from "~/components/canvas/Tldraw";
import { createRelationSchema } from "~/utils/createRelationSchema";
import getDiscourseRelations, {
  type DiscourseRelation,
} from "~/utils/getDiscourseRelations";
import { isRelationComplete } from "~/utils/isRelationComplete";
import refreshConfigTree from "~/utils/refreshConfigTree";
import {
  acceptImportedRelationSchema,
  isAcceptedRelationSchema,
  isProvisionalRelationSchema,
} from "~/utils/relationSchemaAcceptance";
import { isRelationSchemaDeleted } from "~/utils/relationSchemaChanges";

// Roam stores triplets only; a relation type is identified by label + complement.
export type RelationType = { label: string; complement: string };

export const getNodeTypeText = (type: string): string =>
  discourseContext.nodes[type]?.text || type;

type TripletFields = Pick<
  DiscourseRelation,
  "id" | "label" | "complement" | "source" | "destination"
>;

// The canvas tells types apart by label, so hide any type whose label or complement
// the pair already shows in either direction.
export const deriveRelationTypes = ({
  relations,
  shownLabels,
}: {
  relations: TripletFields[];
  shownLabels: string[];
}): RelationType[] => {
  const shown = new Set(shownLabels);
  const seenIds = new Set<string>();
  const types = new Map<string, RelationType>();
  for (const relation of relations) {
    if (seenIds.has(relation.id)) continue;
    seenIds.add(relation.id);
    if (!isAcceptedRelationSchema(relation) || !isRelationComplete(relation))
      continue;
    const { label, complement } = relation;
    if (shown.has(label) || shown.has(complement)) continue;
    const key = JSON.stringify([label, complement]);
    if (!types.has(key)) types.set(key, { label, complement });
  }
  return [...types.values()];
};

const sameText = (a: string, b: string): boolean =>
  a.toLowerCase() === b.toLowerCase();

// Case-insensitive; the canvas keys relation types by label, so one label maps to one complement.
export const validateNewRelationType = ({
  label: rawLabel,
  complement: rawComplement,
  sourceType,
  destinationType,
  relations,
  shownLabels,
}: RelationType & {
  sourceType: string;
  destinationType: string;
  relations: TripletFields[];
  shownLabels: string[];
}): string | null => {
  const label = rawLabel.trim();
  const complement = rawComplement.trim();
  if (!label || !complement) return "Label and complement are required.";

  const shown = shownLabels.find(
    (s) => sameText(s, label) || sameText(s, complement),
  );
  if (shown)
    return `"${shown}" is already a relation between these node types.`;

  const complete = relations.filter(isRelationComplete);
  // createTripletForPair accepts only an exact provisional match for this pair.
  const isAcceptedOnSave = (r: TripletFields): boolean =>
    !isAcceptedRelationSchema(r) &&
    r.label === label &&
    r.complement === complement &&
    r.source === sourceType &&
    r.destination === destinationType;
  const duplicate = complete.find(
    (r) =>
      !isAcceptedOnSave(r) &&
      sameText(r.label, label) &&
      sameText(r.complement, complement),
  );
  if (duplicate)
    return `"${duplicate.label}" already exists. Use Add existing to add it for these node types.`;

  const conflict = complete.find(
    (r) => sameText(r.label, label) && !sameText(r.complement, complement),
  );
  if (conflict)
    return `A relation called "${conflict.label}" already exists with complement "${conflict.complement}".`;

  // A complement reused by another type would show the same label for a reverse drag.
  const others = complete.filter(
    (r) => !(sameText(r.label, label) && sameText(r.complement, complement)),
  );
  const asLabel = others.find((r) => sameText(r.label, complement));
  if (asLabel)
    return `"${asLabel.label}" already exists as a relation. To add it the other way round, drag in the other direction and choose Add existing.`;
  const asComplement = others.find((r) => sameText(r.complement, complement));
  if (asComplement)
    return `"${asComplement.complement}" is already the complement of "${asComplement.label}".`;

  return null;
};

const SCHEMA_WRITE_POLL_MS = 50;
const SCHEMA_WRITE_TIMEOUT_MS = 3000;

// createRelationSchema doesn't await its settings write, so poll until the triplet is readable.
// The legacy store reads the cached config tree, hence the refresh on each pass.
const isRelationReadable = (id: string): boolean => {
  refreshConfigTree();
  return getDiscourseRelations().some((r) => r.id === id);
};

const waitForRelation = async (id: string): Promise<void> => {
  const deadline = Date.now() + SCHEMA_WRITE_TIMEOUT_MS;
  while (!isRelationReadable(id)) {
    if (Date.now() > deadline)
      throw new Error(`Relation ${id} was not readable after saving`);
    await new Promise<void>((resolve) =>
      setTimeout(resolve, SCHEMA_WRITE_POLL_MS),
    );
  }
};

// Saves in drag direction; reuses a matching triplet so repeat picks add nothing.
export const createTripletForPair = async ({
  label,
  complement,
  sourceType,
  destinationType,
}: RelationType & {
  sourceType: string;
  destinationType: string;
}): Promise<string> => {
  // createRelationSchema finds the grammar blocks in the cached config tree.
  refreshConfigTree();
  const existing = getDiscourseRelations().find(
    (r) =>
      !isRelationSchemaDeleted(r.id) &&
      r.label === label &&
      r.complement === complement &&
      r.source === sourceType &&
      r.destination === destinationType,
  );
  if (existing) {
    // A matching imported triplet is accepted rather than duplicated.
    if (isProvisionalRelationSchema(existing.id))
      await acceptImportedRelationSchema(existing.id);
    refreshCanvasRelations();
    return existing.id;
  }
  const id = await createRelationSchema({
    label,
    complement,
    source: sourceType,
    destination: destinationType,
  });
  await waitForRelation(id);
  refreshCanvasRelations();
  return id;
};
import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { TLShapeId, useEditor } from "tldraw";
import { getDiscourseNodeTypeId } from "~/components/canvas/DiscourseNodeUtil";
import {
  deriveRelationTypes,
  getNodeTypeText,
  type RelationType,
} from "~/components/canvas/existingRelationTypes";
import { CreateRelationTypeDialog } from "./CreateRelationTypeDialog";
import { getValidRelationTypesBetween } from "./relationCreation";
import getDiscourseRelations from "~/utils/getDiscourseRelations";
import { useRelationSchemaRevision } from "~/utils/relationSchemaChanges";

export type NodeTypePair = { sourceType: string; targetType: string };

type RelationTypeDropdownProps = {
  sourceId: TLShapeId;
  targetId: TLShapeId;
  dropdownPos: { x: number; y: number };
  onSelect: (relationId: string) => void;
  onDismiss: () => void;
  // Each action renders only when its handler is passed.
  // Resolves true once the type is saved, so the menu returns to the type list.
  onAddExisting?: (args: SaveRelationTypeArgs) => Promise<boolean>;
  onCreateNew?: (args: SaveRelationTypeArgs) => Promise<boolean>;
};

type SaveRelationTypeArgs = { pair: NodeTypePair; relationType: RelationType };

const MENU_ITEM_CLASS =
  "flex w-full cursor-pointer items-center gap-2 rounded-md border-none bg-transparent px-3 py-2 text-left text-[13px] text-[#333] hover:bg-[#f0f0f0]";

const MenuItem = ({
  onClick,
  children,
}: {
  onClick: () => void;
  children: React.ReactNode;
}): React.ReactElement => (
  <button
    onClick={onClick}
    className={MENU_ITEM_CLASS}
    onMouseEnter={(e) => {
      (e.currentTarget as HTMLElement).style.backgroundColor = "#f0f0f0";
    }}
    onMouseLeave={(e) => {
      (e.currentTarget as HTMLElement).style.backgroundColor = "transparent";
    }}
  >
    {children}
  </button>
);

export const RelationTypeDropdown = ({
  sourceId,
  targetId,
  dropdownPos,
  onSelect,
  onDismiss,
  onAddExisting,
  onCreateNew,
}: RelationTypeDropdownProps) => {
  const editor = useEditor();
  const dropdownRef = useRef<HTMLDivElement>(null);
  const [isActionMenuOpen, setIsActionMenuOpen] = useState(false);
  const [isPickerOpen, setIsPickerOpen] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [isCreateOpen, setIsCreateOpen] = useState(false);

  const relationSchemaRevision = useRelationSchemaRevision();
  const validRelationTypes = useMemo(
    () => getValidRelationTypesBetween(editor, sourceId, targetId),
    // relationSchemaRevision re-reads discourseContext.relations after a schema change.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [editor, sourceId, targetId, relationSchemaRevision],
  );

  const pair = useMemo<NodeTypePair | null>(() => {
    const source = editor.getShape(sourceId);
    const target = editor.getShape(targetId);
    if (!source || !target) return null;
    return {
      sourceType: getDiscourseNodeTypeId({ shape: source }),
      targetType: getDiscourseNodeTypeId({ shape: target }),
    };
  }, [editor, sourceId, targetId]);

  // Handle click outside; the dialog renders in a portal outside dropdownRef.
  useEffect(() => {
    const handlePointerDown = (e: PointerEvent) => {
      if (
        !isCreateOpen &&
        dropdownRef.current &&
        !dropdownRef.current.contains(e.target as Node)
      ) {
        onDismiss();
      }
    };

    const timer = setTimeout(() => {
      window.addEventListener("pointerdown", handlePointerDown, true);
    }, 100);

    return () => {
      clearTimeout(timer);
      window.removeEventListener("pointerdown", handlePointerDown, true);
    };
  }, [onDismiss, isCreateOpen]);

  const existingRelationTypes = useMemo(
    () =>
      deriveRelationTypes({
        // Fresh settings, not discourseContext, which keeps removed relations for existing arrows.
        relations: getDiscourseRelations(),
        shownLabels: validRelationTypes.map((t) => t.label),
      }),
    [validRelationTypes],
  );

  // Escape leaves the picker first, then closes the menu.
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // The dialog closes itself on Escape.
      if (e.key !== "Escape" || isCreateOpen) return;
      if (isPickerOpen) {
        e.stopPropagation();
        setIsPickerOpen(false);
      } else {
        onDismiss();
      }
    };
    window.addEventListener("keydown", handleKeyDown, true);
    return () => window.removeEventListener("keydown", handleKeyDown, true);
  }, [onDismiss, isPickerOpen, isCreateOpen]);

  const handlePickExisting = async (
    relationType: RelationType,
  ): Promise<void> => {
    if (!pair || !onAddExisting || isSaving) return;
    setIsSaving(true);
    try {
      if (await onAddExisting({ pair, relationType })) {
        setIsPickerOpen(false);
        setIsActionMenuOpen(false);
      }
    } finally {
      setIsSaving(false);
    }
  };

  const handleSelect = useCallback(
    (relationId: string) => {
      onSelect(relationId);
    },
    [onSelect],
  );

  const actions = pair
    ? [
        onAddExisting && {
          key: "add-existing",
          label: "Add existing…",
          run: () => setIsPickerOpen(true),
        },
        onCreateNew && {
          key: "create-new",
          label: "Create new",
          run: () => setIsCreateOpen(true),
        },
      ].filter((a): a is { key: string; label: string; run: () => void } =>
        Boolean(a),
      )
    : [];
  const isEmpty = validRelationTypes.length === 0;
  const actionItems = actions.map((a) => (
    <MenuItem key={a.key} onClick={a.run}>
      {a.label}
    </MenuItem>
  ));
  const createNewItem = actionItems.find((item) => item.key === "create-new");

  return (
    <div
      ref={dropdownRef}
      style={{
        position: "absolute",
        left: `${dropdownPos.x}px`,
        top: `${dropdownPos.y}px`,
        transform: "translate(-50%, -50%)",
        pointerEvents: "all",
        zIndex: 30,
      }}
      onPointerDown={(e) => e.stopPropagation()}
      onPointerUp={(e) => e.stopPropagation()}
      onClick={(e) => e.stopPropagation()}
    >
      {/* Arbitrary Tailwind values like max-h-[240px] don't apply in Roam, so the cap is inline. */}
      <div
        style={{ maxHeight: 240 }}
        className="min-w-[160px] overflow-y-auto rounded-lg border border-gray-200 bg-white p-4 shadow-lg"
      >
        <div className="flex items-center justify-between px-2 py-1 text-xs font-semibold uppercase tracking-wide text-gray-500">
          <span>Relation Type</span>
          {!isEmpty && !isPickerOpen && actions.length > 0 && (
            <button
              aria-label="Add relation type"
              aria-expanded={isActionMenuOpen}
              onClick={() => setIsActionMenuOpen((open) => !open)}
              className="cursor-pointer rounded border-none bg-transparent px-1 text-sm text-gray-500"
            >
              +
            </button>
          )}
        </div>
        {isPickerOpen && pair ? (
          <>
            <div className="flex items-center gap-1 px-2 py-1 text-[13px] text-gray-500">
              <button
                aria-label="Back to relation types"
                onClick={() => setIsPickerOpen(false)}
                className="cursor-pointer rounded border-none bg-transparent px-1 text-sm text-gray-500"
              >
                ‹
              </button>
              <span>
                {getNodeTypeText(pair.sourceType)} →{" "}
                {getNodeTypeText(pair.targetType)}
              </span>
            </div>
            {existingRelationTypes.length === 0 ? (
              <>
                <div className="px-3 py-2 text-[13px] text-gray-500">
                  No other relation types
                </div>
                {createNewItem}
              </>
            ) : (
              existingRelationTypes.map((rt) => (
                <MenuItem
                  key={JSON.stringify([rt.label, rt.complement])}
                  onClick={() => void handlePickExisting(rt)}
                >
                  {rt.label} / {rt.complement}
                </MenuItem>
              ))
            )}
          </>
        ) : isEmpty ? (
          actionItems.length > 0 ? (
            actionItems
          ) : (
            <div className="px-3 py-2 text-[13px] text-gray-500">
              No relation types between these nodes
            </div>
          )
        ) : (
          <>
            {isActionMenuOpen && (
              <div className="mb-1 border-b border-gray-200 pb-1">
                {actionItems}
              </div>
            )}
            {validRelationTypes.map((rt) => (
              <MenuItem key={rt.id} onClick={() => handleSelect(rt.id)}>
                <span
                  style={{
                    backgroundColor: rt.color,
                  }}
                  className="h-2 w-2 flex-shrink-0 rounded-full bg-[#333]"
                />
                {rt.label}
              </MenuItem>
            ))}
          </>
        )}
      </div>
      {isCreateOpen && pair && onCreateNew && (
        <CreateRelationTypeDialog
          pair={pair}
          shownLabels={validRelationTypes.map((t) => t.label)}
          onClose={() => setIsCreateOpen(false)}
          onSubmit={async (relationType) => {
            const created = await onCreateNew({ pair, relationType });
            if (created) {
              setIsPickerOpen(false);
              setIsActionMenuOpen(false);
            }
            return created;
          }}
        />
      )}
    </div>
  );
};
        if (!sourceBounds || !targetBounds) {
          sourceNodeRef.current = null;
          return;
        }
        const midPage = {
          x: (sourceBounds.midX + targetBounds.midX) / 2,
          y: (sourceBounds.midY + targetBounds.midY) / 2,
        };
        const midVp = editor.pageToViewport(midPage);

        setPending({
          sourceId: selectedNode.id,
          targetId: target.id,
          dropdownPos: midVp,
        });
      };

      containerEl.addEventListener("pointermove", onPointerMove);
      containerEl.addEventListener("pointerup", onPointerUp);
      dragCleanupRef.current = () => {
        containerEl.removeEventListener("pointermove", onPointerMove);
        containerEl.removeEventListener("pointerup", onPointerUp);
        dragCleanupRef.current = null;
      };
    },
    [selectedNode, editor],
  );

  const handleDropdownSelect = useCallback(
    (relationId: string) => {
      if (!pending) return;

      void createDefaultRelationBetweenNodes({
        editor,
        relationId,
        sourceId: pending.sourceId,
        targetId: pending.targetId,
      });

      setPending(null);
      sourceNodeRef.current = null;
    },
    [editor, pending],
  );

  const saveRelationTypeForPair = useCallback(
    async ({
      pair,
      relationType,
      isNew,
    }: {
      pair: NodeTypePair;
      relationType: RelationType;
      isNew: boolean;
    }): Promise<boolean> => {
      try {
        await createTripletForPair({
          ...relationType,
          sourceType: pair.sourceType,
          destinationType: pair.targetType,
        });
      } catch (error) {
        void internalError({
          error,
          type: isNew
            ? "Canvas create relation type"
            : "Canvas add existing relation",
        });
        dispatchToastEvent({
          id: "tldraw-add-existing-relation-error",
          title: isNew
            ? "Could not create relation type"
            : "Could not add discourse relation",
          severity: "error",
        });
        return false;
      }
      if (isNew)
        dispatchToastEvent({
          id: "tldraw-create-relation-type",
          title: "Relation type created",
          severity: "success",
        });
      dispatchToastEvent({
        id: "tldraw-add-existing-relation",
        title: "Discourse relation added",
        description: `${relationType.label} added for ${getNodeTypeText(pair.sourceType)} and ${getNodeTypeText(pair.targetType)}`,
        severity: "success",
      });
      return true;
    },
    [],
  );

  const handleDropdownDismiss = useCallback(() => {
    setPending(null);
    if (sourceNodeRef.current) {
      editor.select(sourceNodeRef.current.id);
    }
    sourceNodeRef.current = null;
  }, [editor]);

import {
  DefaultColorThemePalette,
  Editor,
  TLShapeId,
  createShapeId,
} from "tldraw";
import {
  BaseDiscourseRelationUtil,
  DISCOURSE_RELATION_SHAPE_TYPE,
  DiscourseRelationShape,
  getRelationColor,
} from "~/components/canvas/DiscourseRelationShape/DiscourseRelationUtil";
import { createOrUpdateArrowBinding } from "~/components/canvas/DiscourseRelationShape/helpers";
import { getDiscourseNodeTypeId } from "~/components/canvas/DiscourseNodeUtil";
import {
  getCreatableRelations,
  isDiscourseNodeShape,
} from "~/components/canvas/canvasUtils";
import { checkConnectionType } from "~/utils/findRelationForPair";
import type { DiscourseRelation } from "~/utils/getDiscourseRelations";
import { isRelationComplete } from "~/utils/isRelationComplete";

type RelationTypeOption = { id: string; label: string; color: string };

type DirectionalRelation = Pick<
  DiscourseRelation,
  "label" | "complement" | "source" | "destination"
>;

export const getDirectionalRelationLabel = ({
  relation,
  sourceNodeType,
  targetNodeType,
}: {
  relation: DirectionalRelation;
  sourceNodeType: string;
  targetNodeType: string;
}): string => {
  const { isReverse } = checkConnectionType(
    relation,
    sourceNodeType,
    targetNodeType,
  );
  return isReverse && relation.complement
    ? relation.complement
    : relation.label;
};

export const persistRelationArrow = async ({
  editor,
  arrow,
  targetId,
}: {
  editor: Editor;
  arrow: DiscourseRelationShape;
  targetId: TLShapeId;
}): Promise<void> => {
  const util = editor.getShapeUtil(arrow);
